package com.sep.vox.domain.model.assessment;

import java.time.Instant;
import java.util.UUID;

import com.sep.vox.domain.model.BaseModel;

public class AssessmentSchedule extends BaseModel {
    private UUID assessmentId;
    private UUID schoolRoomId;
    private Instant startDate;
    private Instant endDate;
    private AssessmentScheduleStatus status;
    private UUID movedToScheduleId;

    public AssessmentSchedule() {}

    /**
     * Creates a new schedule in the DRAFT status (the id is generated by the database).
     */
    public static AssessmentSchedule createFresh(UUID assessmentId, UUID schoolRoomId, Instant startDate,
            Instant endDate) {
        return AssessmentSchedule.builder()
                .assessmentId(assessmentId)
                .schoolRoomId(schoolRoomId)
                .startDate(startDate)
                .endDate(endDate)
                .status(AssessmentScheduleStatus.DRAFT)
                .build();
    }

    /**
     * A schedule may only be edited (change room/time) while it is still in status DRAFT.
     */
    public boolean isModifiable() {
        return this.status == AssessmentScheduleStatus.DRAFT;
    }

    /** The start time has been reached. The exact moment {@code startDate} counts as started. */
    public boolean hasStartedAt(Instant now) {
        return this.startDate != null && !this.startDate.isAfter(now);
    }

    /**
     * The end time has passed. The exact moment {@code endDate} counts as time up -- matching the condition
     * {@code endDate > :now} of the queries that enter the exam room ({@code findByIdAndInSchedule}...); if the
     * boundary were off there would be one second in which the schedule is both "not over" and "cannot be entered".
     */
    public boolean hasEndedAt(Instant now) {
        return this.endDate != null && !this.endDate.isAfter(now);
    }

    /**
     * A running session: published, its time has come and it has not ended. The same predicate as
     * {@code findByAssessmentIdAndInSchedule}, rewritten in the domain so that services and workers do not have to copy the
     * {@code Instant} comparison expression.
     */
    public boolean isOngoingAt(Instant now) {
        return this.status == AssessmentScheduleStatus.PUBLISHED && hasStartedAt(now) && !hasEndedAt(now);
    }



    public UUID getAssessmentId() {
        return assessmentId;
    }

    public void setAssessmentId(UUID assessmentId) {
        this.assessmentId = assessmentId;
    }

    public UUID getSchoolRoomId() {
        return schoolRoomId;
    }

    public void setSchoolRoomId(UUID schoolRoomId) {
        this.schoolRoomId = schoolRoomId;
    }

    public Instant getStartDate() {
        return startDate;
    }

    public void setStartDate(Instant startDate) {
        this.startDate = startDate;
    }

    public Instant getEndDate() {
        return endDate;
    }

    public void setEndDate(Instant endDate) {
        this.endDate = endDate;
    }

    public AssessmentScheduleStatus getStatus() {
        return status;
    }

    public void setStatus(AssessmentScheduleStatus status) {
        this.status = status;
    }

    public UUID getMovedToScheduleId() {
        return movedToScheduleId;
    }

    public void setMovedToScheduleId(UUID movedToScheduleId) {
        this.movedToScheduleId = movedToScheduleId;
    }

    public static Builder builder() {
        return new Builder();
    }

    public static class Builder extends BaseModel.Builder<AssessmentSchedule, Builder> {

        private Builder() {
            super(new AssessmentSchedule());
        }

        @Override
        protected Builder self() {
            return this;
        }

        public Builder assessmentId(UUID assessmentId) {
            target.assessmentId = assessmentId;
            return this;
        }

        public Builder schoolRoomId(UUID schoolRoomId) {
            target.schoolRoomId = schoolRoomId;
            return this;
        }

        public Builder startDate(Instant startDate) {
            target.startDate = startDate;
            return this;
        }

        public Builder endDate(Instant endDate) {
            target.endDate = endDate;
            return this;
        }

        public Builder status(AssessmentScheduleStatus status) {
            target.status = status;
            return this;
        }

        public Builder movedToScheduleId(UUID movedToScheduleId) {
            target.movedToScheduleId = movedToScheduleId;
            return this;
        }

    }
}
